import type { SmsReplyIntent, SmsRequestedField } from "../../supabase/functions/_shared/sms-reply-policy"

export type SmsAiReleaseCase = {
  id: string
  style: string
  message: string
  reply: string
  expectedIntent: SmsReplyIntent | "opt_out"
  expectedAutoSafe: boolean
  expectedLanguage: "en" | "es" | "he"
  maxQuestions: number
  requiredFields?: SmsRequestedField[]
  forbiddenText?: RegExp
  event?: "message" | "correction" | "cancellation"
  participantRole?: "customer" | "lead" | "supplier" | "unknown"
  modelAutoSafe?: boolean
}

